96	sealed class OrderStore
97	{
98	    readonly Dictionary<string, Order> _d = new(); readonly object _g = new();
99	    public void Put(string id, Order o) { lock (_g) _d[id] = o; }
100	    public bool TryGet(string id, out Order o) { lock (_g) return _d.TryGetValue(id, out o!); }
101	}
102	
103	sealed class Metrics
104	{
105	    readonly Dictionary<string, long> _c = new(); readonly object _g = new();
106	    public void Inc(string name, string? label = null)
107	    {
108	        var k = label is null ? name : name + "{result=\"" + label + "\"}";
109	        lock (_g) _c[k] = _c.GetValueOrDefault(k) + 1;
110	    }
111	    static readonly double[] Buckets = { 5, 10, 25, 50, 100, 250, 500, 1000, 2500, 5000 };
112	    readonly long[] _hist = new long[Buckets.Length + 1]; double _latSum; long _latCount;
113	    public void ObserveLatency(double ms)
114	    {
115	        lock (_g) { _latSum += ms; _latCount++; int i = 0; while (i < Buckets.Length && ms > Buckets[i]) i++; _hist[i]++; }
116	    }
117	    public string Render(int depth, string version)
118	    {
119	        lock (_g)
120	        {
121	            var sb = new System.Text.StringBuilder();
122	            foreach (var kv in _c.OrderBy(k => k.Key)) sb.Append("oc_").Append(kv.Key).Append(' ').Append(kv.Value).Append('\n');
123	            sb.Append("oc_notify_queue_depth ").Append(depth).Append('\n');
124	            long cum = 0;
125	            for (int i = 0; i < Buckets.Length; i++) { cum += _hist[i]; sb.Append("oc_request_latency_ms_bucket{le=\"").Append(Buckets[i]).Append("\"} ").Append(cum).Append('\n'); }
126	            cum += _hist[Buckets.Length]; sb.Append("oc_request_latency_ms_bucket{le=\"+Inf\"} ").Append(cum).Append('\n');
127	            sb.Append("oc_request_latency_ms_sum ").Append(Math.Round(_latSum, 1)).Append('\n').Append("oc_request_latency_ms_count ").Append(_latCount).Append('\n');
128	            sb.Append("oc_gc_heap_bytes ").Append(GC.GetTotalMemory(false)).Append('\n');
129	            sb.Append("oc_working_set_bytes ").Append(Environment.WorkingSet).Append('\n');
130	            sb.Append("oc_gc_collections_gen2 ").Append(GC.CollectionCount(2)).Append('\n');
131	            sb.Append("oc_info{version=\"").Append(version).Append("\"} 1\n");
132	            return sb.ToString();
133	        }
134	    }
135	}
136	
137	sealed class JsonlLog
138	{
139	    readonly string _p; readonly string _v; readonly object _g = new();
140	    public JsonlLog(string p, string v) { _p = p; _v = v; }
141	    public void Write(object o)
142	    {
143	        var d = JsonSerializer.SerializeToNode(o)!.AsObject();
144	        d["ts"] = DateTimeOffset.Now.ToString("o"); d["version"] = _v;
145	        lock (_g) File.AppendAllText(_p, d.ToJsonString() + "\n");
146	    }
147	}
148	
149	// 演練注入 retain_payloads 的落點（v1.2.0 修復後）：客服查詢暫存改為有上限的環狀緩衝——最多 MaxItems 筆、每筆只留前 MaxBodyChars 字與原長度。
150	// v1.1.0 之前是無上限的 List，壓力下把 heap 撐到上限（見 evidence/runs/oom-retained-payloads-*、diagnosis/oom）。
151	static class Retained
152	{
153	    const int MaxItems = 256, MaxBodyChars = 256;
154	    static readonly Queue<(string OrderId, string Head, int Length)> _items = new(); static readonly object _g = new();
155	    public static void Keep(string orderId, string? body)
156	    {
157	        var b = body ?? "";
158	        lock (_g) { _items.Enqueue((orderId, b.Length > MaxBodyChars ? b[..MaxBodyChars] : b, b.Length)); while (_items.Count > MaxItems) _items.Dequeue(); }
159	    }
160	    public static int Count { get { lock (_g) return _items.Count; } }
161	}
162	
163	sealed class Faults
164	{
165	    public int? DropOverQueue; public int DelayMs; public bool RetainPayloads; public bool SyncNotify;
166	    public bool Any => DropOverQueue is not null || DelayMs > 0 || RetainPayloads || SyncNotify;
167	    public static Faults Load(string? path)
168	    {
169	        var f = new Faults();
170	        if (string.IsNullOrEmpty(path) || !File.Exists(path)) return f;
171	        using var doc = JsonDocument.Parse(File.ReadAllText(path)); var r = doc.RootElement;
172	        if (r.TryGetProperty("notify_drop_over_queue", out var q)) f.DropOverQueue = q.GetInt32();
173	        if (r.TryGetProperty("notify_delay_ms", out var d)) f.DelayMs = d.GetInt32();
174	        if (r.TryGetProperty("retain_payloads", out var rp)) f.RetainPayloads = rp.GetBoolean();
175	        if (r.TryGetProperty("sync_notify", out var sn)) f.SyncNotify = sn.GetBoolean();
176	        return f;
177	    }
178	}
179	
180	// 通知 worker：從 channel 取出 → POST sink → 失敗重試 3 次（200／400／800 ms）→ 超過進 dead_letter（NC-05）。
181	// 故障 notify_drop_over_queue（演練用）：佇列深度超過 N 時觸發「壓力延後」路徑。
182	// v1.0.0 的行為是記一行 notify_deferred 後不再重送、sent 計數照加（服務說送了、接收端沒收據）；v1.1.0 改為重排到隊尾、sent 只在 ack 後才加。
183	// 這條故障設計移植自 O 服務 fault-A；是演練用注入，不是自然事故。
184	sealed class NotificationWorker : BackgroundService
185	{
186	    readonly Channel<Notification> _ch; readonly Metrics _m; readonly JsonlLog _log; readonly Faults _f; readonly HttpClient _http = new();
187	    readonly string _sink = Environment.GetEnvironmentVariable("OC_SINK_URL") ?? "http://127.0.0.1:5081/notify";
188	    static readonly int[] Backoff = { 200, 400, 800 };
189	    const int MaxDeferrals = 5;
190	    public NotificationWorker(Channel<Notification> ch, Metrics m, JsonlLog log, Faults f) { _ch = ch; _m = m; _log = log; _f = f; }
191	    static readonly HttpClient SharedHttp = new();
192	    /// 同步送一次（含重試），供 sync_notify 演練路徑使用；計數規則與 worker 相同。
193	    public static async Task SendOnce(Notification n, Metrics m, JsonlLog log, string sink)
194	    {
195	        bool sent = false;
196	        for (int attempt = 0; attempt <= Backoff.Length && !sent; attempt++)
197	        {
198	            try
199	            {
200	                var body = JsonSerializer.Serialize(new { notification_id = n.NotificationId, order_id = n.OrderId, request_id = n.RequestId, run_id = n.RunId, kind = n.Kind, refund_requested = n.RefundRequested, attempt });
201	                var resp = await SharedHttp.PostAsync(sink, new StringContent(body, System.Text.Encoding.UTF8, "application/json"));
202	                sent = resp.IsSuccessStatusCode;
203	            }
204	            catch (Exception e) { log.Write(new { level = "WARN", @event = "notify_attempt_failed", notification_id = n.NotificationId, attempt, error = e.GetType().Name }); }
205	            if (!sent && attempt < Backoff.Length) await Task.Delay(Backoff[attempt]);
206	        }
207	        if (sent) { m.Inc("notify_sent_total"); log.Write(new { level = "INFO", @event = "notify_sent", notification_id = n.NotificationId, order_id = n.OrderId, request_id = n.RequestId, run_id = n.RunId, sync = true }); }
208	        else { m.Inc("notify_failed_total"); m.Inc("notify_dead_letter_total"); log.Write(new { level = "ERROR", @event = "notify_dead_letter", notification_id = n.NotificationId, order_id = n.OrderId, request_id = n.RequestId, run_id = n.RunId, attempts = Backoff.Length + 1 }); }
209	    }
210	    protected override async Task ExecuteAsync(CancellationToken ct)
211	    {
212	        await foreach (var n in _ch.Reader.ReadAllAsync(ct))
213	        {
214	            if (_f.DelayMs > 0) await Task.Delay(_f.DelayMs, ct);
215	            if (_f.DropOverQueue is int q && _ch.Reader.Count > q)
216	            {   // v1.1.0 修復：壓力下不再「假裝送了」。延後＝重排到隊尾（最多 MaxDeferrals 次），sent_total 只在接收端 ack 後才加；延後另計。
217	                if (n.Deferrals < MaxDeferrals)
218	                {
219	                    _m.Inc("notify_deferred_total");
220	                    _log.Write(new { level = "INFO", @event = "notify_deferred", notification_id = n.NotificationId, order_id = n.OrderId, request_id = n.RequestId, run_id = n.RunId, queue_depth = _ch.Reader.Count, deferrals = n.Deferrals + 1, requeued = true });
221	                    await _ch.Writer.WriteAsync(n with { Deferrals = n.Deferrals + 1 }, ct);
222	                    continue;
223	                }
224	                _log.Write(new { level = "WARN", @event = "notify_deferral_limit", notification_id = n.NotificationId, deferrals = n.Deferrals, note = "超過延後上限，改走一般送出／重試路徑" });
225	            }
226	            bool sent = false;
227	            for (int attempt = 0; attempt <= Backoff.Length && !sent; attempt++)
228	            {
229	                try
230	                {
231	                    var body = JsonSerializer.Serialize(new { notification_id = n.NotificationId, order_id = n.OrderId, request_id = n.RequestId, run_id = n.RunId, kind = n.Kind, refund_requested = n.RefundRequested, attempt });
232	                    var resp = await _http.PostAsync(_sink, new StringContent(body, System.Text.Encoding.UTF8, "application/json"), ct);
233	                    sent = resp.IsSuccessStatusCode;
234	                    if (!sent) _log.Write(new { level = "WARN", @event = "notify_attempt_failed", notification_id = n.NotificationId, attempt, status = (int)resp.StatusCode });
235	                }
236	                catch (Exception e) when (!ct.IsCancellationRequested)
237	                {
238	                    _log.Write(new { level = "WARN", @event = "notify_attempt_failed", notification_id = n.NotificationId, attempt, error = e.GetType().Name });
239	                }
240	                if (!sent && attempt < Backoff.Length) await Task.Delay(Backoff[attempt], ct);
241	            }
242	            if (sent)
243	            {
244	                _m.Inc("notify_sent_total");
245	                _log.Write(new { level = "INFO", @event = "notify_sent", notification_id = n.NotificationId, order_id = n.OrderId, request_id = n.RequestId, run_id = n.RunId });
246	            }
247	            else
248	            {
249	                _m.Inc("notify_failed_total"); _m.Inc("notify_dead_letter_total");
250	                _log.Write(new { level = "ERROR", @event = "notify_dead_letter", notification_id = n.NotificationId, order_id = n.OrderId, request_id = n.RequestId, run_id = n.RunId, attempts = Backoff.Length + 1 });
251	            }
252	        }
253	    }
254	}
